using Cell = std::pair<int, int>;

double diagonal_sum(std::map<Cell, double>& sparse, int n) {
    double total = 0.0;
    for (int i = 0; i < n; ++i) {
        total += sparse[{i, i}];
    }
    return total;
}

int main() {
    std::map<Cell, double> sparse{
        {{0, 0}, 2.5}, {{1, 2}, 4.0}, {{2, 2}, 1.5}};

    const double total = diagonal_sum(sparse, 3);
    std::cout << total << ' ' << sparse.size() << ' '
              << sparse.count({1, 1}) << '\n';
}

