std::size_t with_prefix(const std::set<std::string, std::less<>>& dict,
                        std::string_view prefix) {
    std::size_t n = 0;
    for (auto it = dict.lower_bound(prefix); it != dict.end(); ++it) {
        if (it->compare(0, prefix.size(), prefix) != 0) {
            break;
        }
        ++n;
    }
    return n;
}

