#include <cctype>
#include <cstddef>
#include <string>
#include <unordered_set>

struct CaseFoldHash {
    std::size_t operator()(const std::string& word) const noexcept {
        std::size_t h = 14695981039346656037ULL;
        for (unsigned char c : word) {
            h ^= static_cast<std::size_t>(std::tolower(c));
            h *= 1099511628211ULL;
        }
        return h;
    }
};

struct CaseFoldEqual {
    bool operator()(const std::string& a,
                    const std::string& b) const noexcept {
        if (a.size() != b.size()) {
            return false;
        }
        for (std::size_t i = 0; i < a.size(); ++i) {
            if (std::tolower(static_cast<unsigned char>(a[i])) !=
                std::tolower(static_cast<unsigned char>(b[i]))) {
                return false;
            }
        }
        return true;
    }
};

using Dictionary =
    std::unordered_set<std::string, CaseFoldHash, CaseFoldEqual>;

bool is_known(const Dictionary& dict, const std::string& word) {
    return dict.find(word) != dict.end();
}

#include <functional>
#include <map>
#include <string>
#include <string_view>

using Frequencies = std::map<std::string, int, std::less<>>;

void tally(Frequencies& freq, std::string_view word) {
    const auto found = freq.find(word);   // transparent: no temporary key
    if (found != freq.end()) {
        ++found->second;                  // hot path: no allocation at all
        return;
    }
    freq.emplace(std::string{word}, 1);   // first sighting pays for the key
}

#include <cstddef>
#include <map>
#include <string>

void dispatch(const std::string& task);

std::size_t run_due(std::multimap<int, std::string>& schedule, int now) {
    const auto last = schedule.upper_bound(now);  // first task strictly later

    std::size_t ran = 0;
    for (auto it = schedule.begin(); it != last; ++it) {
        dispatch(it->second);
        ++ran;
    }

    schedule.erase(schedule.begin(), last);
    return ran;
}

#include <cstddef>
#include <unordered_map>

class HitCounters {
public:
    explicit HitCounters(std::size_t expected) {
        channels_.reserve(expected);  // elements, not buckets
    }

    // The returned pointer stays valid across later open() and record()
    // calls: an insertion may rehash, and a rehash relinks the existing
    // nodes into a new bucket array without moving the elements. An
    // iterator would not survive that; a pointer or reference does.
    long* open(int channel) {
        auto [position, inserted] = channels_.try_emplace(channel, 0);
        return &position->second;
    }

    void record(int channel) { ++*open(channel); }

    std::size_t live() const { return channels_.size(); }

private:
    std::unordered_map<int, long> channels_;
};

#include <cstdint>
#include <flat_map>
#include <optional>
#include <string>
#include <utility>
#include <vector>

using Zones = std::flat_map<std::uint32_t, std::string>;

Zones build_zones(std::vector<std::pair<std::uint32_t, std::string>> starts) {
    // One bulk construction sorts once: O(n log n) over contiguous storage.
    // Inserting row by row would shift a tail each time, so O(n^2) overall.
    return Zones(starts.begin(), starts.end());
}

std::optional<std::string> zone_of(const Zones& zones, std::uint32_t address) {
    auto above = zones.upper_bound(address);  // first start > address
    if (above == zones.begin()) {
        return std::nullopt;                  // below every zone start
    }
    --above;                                  // the zone that contains it
    return above->second;
}

#include <map>
#include <string>
#include <utility>

struct Session {
    std::string user;
    int requests;
};

using Sessions = std::map<std::string, Session>;

bool retire(Sessions& active, Sessions& idle, const std::string& id) {
    auto node = active.extract(id);
    if (node.empty()) {
        return false;  // no such session
    }

    auto result = idle.insert(std::move(node));
    if (!result.inserted) {
        // result.node still owns the element; return it to active so the
        // failed move loses nothing. Neither step allocates.
        active.insert(std::move(result.node));
        return false;
    }
    return true;
}
